          a: { type: 'number', description: 'The first operand.' },
          b: { type: 'number', description: 'The second operand.' },
          operation: {
            type: 'string',
            enum: ['add', 'subtract', 'multiply', 'divide'],
            description: 'The arithmetic operation to perform.',
          },
        },
        required: REQUIRED_KEYS,
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const input = args || {};

  // Reject missing or extra fields.
  const presentKeys = Object.keys(input);
  for (const key of presentKeys) {
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }
  for (const key of REQUIRED_KEYS) {
    if (!(key in input)) {
      throw new Error(`Missing required field: ${key}`);
    }
  }

  const { a, b, operation } = input;

  // Validate numeric operands.
  if (!isNumber(a)) {
    throw new Error('Field "a" must be a finite number');
  }
  if (!isNumber(b)) {
    throw new Error('Field "b" must be a finite number');
  }

  // Validate operation.
  if (typeof operation !== 'string' || !Object.prototype.hasOwnProperty.call(OPERATIONS, operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  // Reject division by zero.
  if (operation === 'divide' && b === 0) {
    throw new Error('Division by zero');
  }

  const result = OPERATIONS[operation](a, b);

  if (!Number.isFinite(result)) {
    throw new Error('Operation produced a non-finite result');
  }

  return {
    content: [{ type: 'text', text: String(result) }],
  };
}
